// Game Profile (Takaro Generic Game Protocol v1): who this connector is, the `game.profile`
// capability and the `getGameIcon` answer. The icon is compiled in (game_icon_png.inc, generated by
// tools/gen_game_icon.py from games/enshrouded/assets/icon-256.png); its revision and size are
// computed from those bytes, never written by hand.
#pragma once
#include "native/json_util.h"

#include <string>

namespace native {

constexpr const char* kGameSlug = "enshrouded";
constexpr const char* kConnectorName = "takaro-enshrouded";
constexpr const char* kGameDisplayName = "Enshrouded";
extern const char* const kConnectorVersion;  // TAKARO_PLUGIN_VERSION, rewritten by release-please

// The PNG bytes and the first 12 hex characters of their sha256.
const std::string& GameIconPng();
const std::string& GameIconRevision();
std::string Sha256Hex(const std::string& bytes);

// The `game.profile` manifest entry. `gameVersion` is the running game build (the kfc build number,
// for example "1269579"); it is trimmed and omitted unless it is 1-32 printable ASCII characters.
std::string GameProfileCapability(const std::string& gameVersion);
// The getGameIcon response payload { revision, data }.
JsonValue GameIconPayload();

}  // namespace native
